-- ============================================================
-- 语法骨架扩展：15 个高频句型
-- ============================================================
INSERT OR IGNORE INTO cards_master (id, type, content, phonetic, definition, grammar_pattern, explanation, examples_json, frequency_rank, tags, difficulty, source) VALUES
('g-011','grammar','used to do sth.','/juːst tuː duː/','过去常常做某事（现在不做了）','used to + 动词原形','只讲过去的习惯，暗含「现在不是这样」。否定和疑问用 didn''t use to / did you use to，注意这里没有 d。别和 be used to doing（习惯于）搞混。','[{"scene":"回忆","en":"I used to walk to school.","zh":"我以前走路上学。"},{"scene":"变化","en":"She didn''t use to like coffee.","zh":"她以前不喜欢咖啡。"},{"scene":"对比","en":"We used to meet every Friday.","zh":"我们以前每周五都见面。"}]',401,'["句型","过去习惯","易混"]',3,'seed'),
('g-012','grammar','be going to do sth.','/biː ˈɡəʊɪŋ tuː/','打算做某事；即将发生','be going to + 动词原形','两个用法：一是「已经计划好」，二是有明显迹象的预测（看天要下雨）。和 will 的区别在于「有没有提前打算」。','[{"scene":"计划","en":"I''m going to quit sugar next month.","zh":"我下个月打算戒糖。"},{"scene":"预测","en":"Look at those clouds — it''s going to rain.","zh":"看那云，要下雨了。"},{"scene":"职场","en":"We''re going to launch on Friday.","zh":"我们打算周五上线。"}]',402,'["句型","将来"]',2,'seed'),
('g-013','grammar','have been doing sth.','/həv biːn ˈduːɪŋ/','一直在做某事（强调持续到现在）','have/has been + 动词-ing','强调动作从过去延续到现在、可能还在继续，常和 for / since / all day 连用。和 have done 的区别是：后者强调「做完了」，前者强调「一直在做」。','[{"scene":"日常","en":"I''ve been learning English for two years.","zh":"我学英语两年了。"},{"scene":"职场","en":"We''ve been waiting for your reply.","zh":"我们一直在等你的回复。"},{"scene":"抱怨","en":"You''ve been staring at your phone all morning.","zh":"你整个上午都在盯手机。"}]',403,'["句型","时态","完成进行"]',4,'seed'),
('g-014','grammar','as soon as ...','/əz suːn əz/','一……就……','as soon as + 从句，主句','连接两个紧接发生的动作。注意「主将从现」：主句用将来时，as soon as 从句用一般现在时。','[{"scene":"职场","en":"I''ll call you as soon as I land.","zh":"我一落地就给你打电话。"},{"scene":"日常","en":"As soon as he arrived, it started raining.","zh":"他一到就下起雨来。"},{"scene":"安排","en":"We''ll start as soon as everyone is here.","zh":"人一到齐我们就开始。"}]',404,'["句型","时间从句"]',3,'seed'),
('g-015','grammar','unless ...','/ənˈles/','除非；如果不','unless + 从句','等于 if ... not，但语气更「设限」。注意 unless 从句里不用再加 not，写了 unless ... not 就变成双重否定了。','[{"scene":"规则","en":"You can''t enter unless you have a badge.","zh":"没有工牌不能进。"},{"scene":"职场","en":"We''ll ship it unless QA finds a blocker.","zh":"除非测试发现阻塞问题，否则我们就发。"},{"scene":"日常","en":"I won''t go unless you come with me.","zh":"你不陪我我就不去。"}]',405,'["句型","条件从句"]',3,'seed'),
('g-016','grammar','even if ...','/ˈiːvn ɪf/','即使……（也）','even if + 从句，主句','表示「就算是这种情况，结果也不变」。和 even though 的区别：even if 是假设，even though 是事实。','[{"scene":"职场","en":"Even if we hurry, we''ll be late.","zh":"就算赶也来不及了。"},{"scene":"态度","en":"I''ll support you even if you''re wrong.","zh":"就算你错了我也支持你。"},{"scene":"日常","en":"Even if it rains, we''re going.","zh":"就算下雨我们也去。"}]',406,'["句型","让步从句","易混"]',4,'seed'),
('g-017','grammar','in order to do sth.','/ɪn ˈɔːdə tuː/','为了做某事','in order to + 动词原形 / in order that + 从句','比 to do 更正式、更强调目的，常用于书面。否定形式是 in order not to do。','[{"scene":"职场","en":"We simplified it in order to save time.","zh":"为了省时间我们做了简化。"},{"scene":"学习","en":"She reads aloud in order to improve pronunciation.","zh":"她朗读是为了改进发音。"},{"scene":"日常","en":"I left early in order not to miss the train.","zh":"我早走是为了不错过火车。"}]',407,'["句型","目的"]',3,'seed'),
('g-018','grammar','too + adj. + to do sth.','/tuː ... tuː/','太……以至于不能……','too + 形容词/副词 + to + 动词原形','形式是肯定、意思是否定（太…所以做不到）。想表达「足够…能做」要用 enough to，别混。','[{"scene":"日常","en":"I''m too tired to cook tonight.","zh":"我太累了，今晚不做饭了。"},{"scene":"职场","en":"It''s too early to tell.","zh":"现在下结论太早。"},{"scene":"消费","en":"It''s too expensive to justify.","zh":"太贵了，不划算。"}]',408,'["句型","程度"]',3,'seed'),
('g-019','grammar','adj./adv. + enough to do sth.','/ɪˈnʌf tuː/','足够……可以做某事','形容词/副词 + enough + to + 动词原形','enough 必须放在形容词**后面**（good enough），这是中国学习者最常见的语序错误。修饰名词时才放前面（enough time）。','[{"scene":"日常","en":"He''s old enough to decide for himself.","zh":"他够大，可以自己决定了。"},{"scene":"职场","en":"The sample is good enough to show clients.","zh":"这个样品够好，可以给客户看。"},{"scene":"日常","en":"I didn''t wake up early enough to catch it.","zh":"我起得不够早，没赶上。"}]',409,'["句型","语序"]',3,'seed'),
('g-020','grammar','prefer A to B','/prɪˈfɜː ... tuː/','比起 B 更喜欢 A','prefer + 名词/doing + to + 名词/doing','注意搭配是 to 而不是 than；如果两边都是动作，要用 doing。想用 than 就得换成 would rather A than B。','[{"scene":"偏好","en":"I prefer tea to coffee.","zh":"比起咖啡我更喜欢茶。"},{"scene":"日常","en":"She prefers walking to taking the bus.","zh":"她宁愿走路也不坐公交。"},{"scene":"职场","en":"I prefer async to long meetings.","zh":"比起长会我更喜欢异步沟通。"}]',410,'["句型","偏好","易混"]',3,'seed'),
('g-021','grammar','would like to do sth.','/wʊd laɪk tuː/','想要做某事（礼貌）','would like to + 动词原形','比 want 委婉，适合请求和提议。疑问句 Would you like ...? 是邀请，回答用 Yes, please / No, thanks。','[{"scene":"请求","en":"I''d like to ask a quick question.","zh":"我想快速问个问题。"},{"scene":"邀请","en":"Would you like to join us for lunch?","zh":"要一起吃饭吗？"},{"scene":"职场","en":"We''d like to move the call to Thursday.","zh":"我们想把电话会挪到周四。"}]',411,'["句型","礼貌"]',2,'seed'),
('g-022','grammar','make sb. do sth.','/meɪk ... duː/','使某人做某事','make + 宾语 + 动词原形（不加 to）','使役动词 make / let / have 后面都跟动词原形；但被动语态里 to 会回来（be made to do）。','[{"scene":"日常","en":"That song makes me want to dance.","zh":"那首歌让我想跳舞。"},{"scene":"职场","en":"The delay made us rethink the plan.","zh":"这次延迟让我们重新考虑方案。"},{"scene":"被动","en":"We were made to wait two hours.","zh":"我们被迫等了两小时。"}]',412,'["句型","使役"]',3,'seed'),
('g-023','grammar','not only ... but also ...','/nɒt ˈəʊnli ... bʌt ˈɔːlsəʊ/','不仅……而且……','not only + A + but also + B','连接两个并列成分，形式要对称（名词配名词、句子配句子）。not only 放句首时主句要部分倒装。','[{"scene":"职场","en":"She''s not only fast but also accurate.","zh":"她不仅快而且准。"},{"scene":"产品","en":"It saves time and also reduces errors.","zh":"既省时间又减少错误。"},{"scene":"倒装","en":"Not only did he finish early, but he also helped others.","zh":"他不仅提前做完，还帮了别人。"}]',413,'["句型","并列"]',4,'seed'),
('g-024','grammar','It seems that ...','/ɪt siːmz ðæt/','看起来……；似乎……','It seems (to sb.) that + 从句 / sb. seems to do','用来软化判断，避免说得太绝对。口语里常简化成 It seems so / It seems not。','[{"scene":"判断","en":"It seems that nobody noticed.","zh":"好像没人注意到。"},{"scene":"职场","en":"It seems to me that we''re overthinking.","zh":"在我看来我们想多了。"},{"scene":"日常","en":"He seems to know the answer.","zh":"他好像知道答案。"}]',414,'["句型","判断"]',3,'seed'),
('g-025','grammar','The reason why ... is that ...','/ðə ˈriːzn waɪ ... ɪz ðæt/','……的原因是……','The reason why + 从句 + is that + 从句','书面表达因果的完整句式。注意后面用 that 而不是 because —— 说 the reason is because 是常见错。','[{"scene":"职场","en":"The reason why we''re late is that the data was wrong.","zh":"我们延误的原因是数据错了。"},{"scene":"解释","en":"The reason why I asked is that I''m not sure.","zh":"我问的原因是我也不确定。"},{"scene":"书面","en":"The main reason why people quit is stress.","zh":"人们离职的主要原因是压力。"}]',415,'["句型","因果","书面"]',4,'seed');
